using System.Windows.Forms;using SobhanNotificationHub.Services;namespace SobhanNotificationHub.Tray;public static class TrayMenuService{public static ContextMenuStrip Build(TrayIconService tray,AppServices services){var menu=new ContextMenuStrip{RightToLeft=RightToLeft.Yes};void Add(string text,Action action)=>menu.Items.Add(text,null,(s,e)=>action());Add("باز کردن پنل سبحان",()=>tray.OpenPanel("/admin/"));Add("پیام‌های من",()=>tray.OpenPanel("/messenger/"));Add("کارتابل من",()=>tray.OpenPanel("/admin/cartable.php"));Add("تیکت‌های من",()=>tray.OpenPanel("/admin/tickets.php"));menu.Items.Add(new ToolStripSeparator());Add("تاریخچه اعلان‌ها",tray.ShowHistory);Add("تنظیمات اعلان",tray.ShowSettings);Add("اتصال / تغییر حساب",tray.ShowConnect);Add("بررسی پیام‌ها",async()=>{try{await PollingWorker.PollOnceAsync(services,CancellationToken.None);}catch(Exception ex){LoggingService.Error("manual_poll",ex);}});var startup=new ToolStripMenuItem("اجرا با شروع ویندوز"){Checked=StartupService.IsEnabled,CheckOnClick=true};startup.CheckedChanged+=(s,e)=>StartupService.Set(startup.Checked);menu.Items.Add(startup);Add("درباره برنامه",tray.ShowAbout);menu.Items.Add(new ToolStripSeparator());Add("خروج",tray.Exit);return menu;}}
